export function stageGroup(w){if(w.stage>=journeys[w.kind].steps.length)return 3;return w.stage===0?0:w.stage<3?1:2;}
export function validateWorkspaceUrl(raw,p){if(!raw)return '';let url;try{url=new URL(raw);}catch{throw new Error('Enter a valid HTTPS workspace URL.');}if(url.protocol!=='https:'||url.username||url.password||!p.domains.some(d=>url.hostname===d||url.hostname.endsWith('.'+d)))throw new Error('Use an approved HTTPS domain for this platform.');if([...url.searchParams.keys()].some(k=>/token|secret|key|auth|code|password/i.test(k)))throw new Error('Do not save secret, signed or authentication URLs.');if(url.hash)throw new Error('Remove the URL fragment before saving a workspace shortcut.');return url.href;}
